const EDITOR="<!doctype html><html lang=\"ko\" data-theme=\"품목\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>품목 수정 · 홍열이네</title><style>:root{color-scheme:light;--ink:#262018;--muted:#655c51;--paper:#fffdf9;--line:#e7e0d5;--accent:#a83223;--deep:#27211c;--warm:#f6f2eb}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--warm);color:var(--ink);font:1rem/1.55 system-ui,-apple-system,\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\nbutton:disabled{cursor:default;opacity:.53}\nbutton:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #c9654b;outline-offset:2px}\n.wrap{width:min(1160px,calc(100% - 48px));margin:auto}\n.mast{background:var(--deep);color:#fff8ee}\n.header-inner{min-height:69px;display:flex;align-items:center;justify-content:space-between;gap:16px}\n.brand{display:flex;align-items:center;gap:11px;font-size:1.13rem;font-weight:850;letter-spacing:-.035em}\n.seal{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:#b63829;color:white}\n.header-label{font-size:.875rem;color:#eadccd}\n.hero{display:flex;align-items:end;justify-content:space-between;gap:24px;padding:42px 0 27px}\n.eyebrow{color:var(--accent);font-size:.875rem;font-weight:800;display:flex;align-items:center;gap:8px}\n.eyebrow span{width:17px;height:2px;background:currentColor}\nh1,h2,h3,p{margin:0}\nh1{font-size:clamp(2.5rem,6vw,3.75rem);line-height:1.16;letter-spacing:-.07em;margin:6px 0 7px}\n.hero p,.panel-header p,.storage{color:var(--muted)}\n.filters{display:flex;gap:12px}\nlabel{display:grid;gap:5px;font-weight:700;font-size:.875rem;color:var(--muted)}\ninput,select{min-width:0;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:1rem}\nselect{appearance:none;padding-right:32px;min-width:105px;background-image:linear-gradient(45deg,transparent 50%,#6a5c51 50%),linear-gradient(135deg,#6a5c51 50%,transparent 50%);background-position:right 16px center,right 11px center;background-size:5px 5px;background-repeat:no-repeat}\n.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:20px;align-items:start;padding-bottom:42px}\n.panel{background:var(--paper);border:1px solid var(--line);border-radius:17px;overflow:hidden;box-shadow:0 3px 10px #38240007}\n.panel-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:19px 21px 14px}\nh2{font-size:1.32rem;letter-spacing:-.035em}\n.panel-header p{font-size:.875rem;margin-top:2px}\n.search{position:relative;display:block;width:min(200px,46%)}\n.search span{position:absolute;left:11px;top:4px;font-size:1.36rem;pointer-events:none}\n.search input{width:100%;padding-left:32px}\n.categories{display:flex;flex-wrap:wrap;gap:6px;padding:0 20px 15px;border-bottom:1px solid var(--line)}\n.category{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:8px;padding:5px 8px;font-size:.875rem;font-weight:650}\n.category[aria-pressed=true]{background:var(--deep);color:white;border-color:var(--deep)}\n.group h3{font-size:.875rem;padding:8px 20px;background:#f7f3eb;color:#5e5145}\n.product{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 20px;border-bottom:1px solid #f0eae0;min-height:44px}\n.product button,.remove{border:1px solid #ecd7cb;border-radius:7px;background:#fff6ef;color:#922b1f;padding:3px 9px;font-size:.875rem;font-weight:700}\n.product button:disabled{opacity:.85;background:#f4efe8;border-color:var(--line);color:var(--muted)}\n.count{display:inline-block;vertical-align:2px;color:var(--accent);background:#f9e9e0;border-radius:7px;padding:0 7px;font-size:.875rem;margin-left:4px}\n.order-list{border-top:1px solid var(--line)}\n.empty{padding:34px 21px;color:var(--muted);text-align:center}\n.line{padding:11px 20px;border-bottom:1px solid #f0eae0}\n.line-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}\n.line-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}\n.line-fields label:last-child{grid-column:1/-1}\n.footer{padding:16px 20px}\n.primary{width:100%;border:0;border-radius:9px;background:var(--accent);color:white;padding:10px;font-weight:800}\n.primary:hover:enabled{background:#8c271b}\n.storage,.status{font-size:.875rem;margin-top:8px}\n.status:empty{display:none}\n.status{color:var(--accent)}\n.copy-field{width:100%;min-height:120px;margin-top:10px;font:inherit}\n@media(max-width:760px){.layout{grid-template-columns:1fr}.hero{align-items:start;flex-direction:column;padding-top:28px;gap:16px}.wrap{width:calc(100% - 28px)}.order{grid-row:1}.order-list .empty{padding:15px 20px}.filters{flex-wrap:wrap}}\n[data-theme=\"시청점\"]{--accent:#175595;--tint:#e9f2fb}\n[data-theme=\"인제점\"]{--accent:#166448;--tint:#e5f4ec}\n[data-theme=\"노형점\"]{--accent:#994315;--tint:#fff0e1}\n[data-theme=\"사모님\"]{--accent:#693b88;--tint:#f4edf8}\n[data-theme=\"품목\"]{--accent:#455368;--tint:#edf0f5}\nbody{background:var(--tint)}\n.mast,.category[aria-pressed=true]{background:var(--accent)}\n.header-label{color:white;font-weight:750}\n.primary:hover:enabled{background:var(--accent);filter:brightness(.88)}\n.product button,.count,#branch{color:var(--accent);background-color:var(--tint);border-color:var(--accent)}\n#branch{font-weight:800}\n.ticket{border-left:5px solid var(--accent);margin:12px 0;padding:12px;background:#fff}\n.branch-badge{display:inline-block;background:var(--accent);color:white;border-radius:6px;padding:2px 9px;margin-right:8px}\n.categories{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:8px}.category{min-height:42px;font-weight:750;color:var(--ink);background:white}.category[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:white}.group h3{font-size:1rem;border-left:5px solid var(--accent);background:var(--tint);color:var(--accent)}#total{display:block;margin-bottom:8px}.product{display:grid;grid-template-columns:minmax(0,1fr) minmax(48px,72px) minmax(68px,104px) 64px;gap:8px;align-items:center}\n.product-name{overflow-wrap:anywhere}.row-field{font-size:.8rem;gap:2px}.row-field input{width:100%;padding:6px;font-variant-numeric:tabular-nums}.product button{min-height:42px;padding:3px}\n@media(max-width:480px){.product{padding:8px 10px;grid-template-columns:minmax(0,1fr) 49px 69px 51px;gap:5px}.product-name{font-size:.94rem}}\n.product{grid-template-columns:minmax(0,1fr) auto auto}.product button{grid-column:3;min-width:54px}.product-heading{display:flex;align-items:baseline;flex-wrap:wrap;gap:2px 12px}.product-values,.cart-quantity{font-size:.875rem;color:var(--muted)}.cart-quantity{color:var(--accent);font-weight:700}.ticket-scroll{max-width:100%;overflow-x:auto;margin:10px 0}\n.ticket-items{width:100%;border-collapse:collapse;font-size:1rem;line-height:1.4;font-variant-numeric:tabular-nums}\n.ticket-items th,.ticket-items td{padding:7px 4px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}\n.ticket-items thead th{font-size:.875rem;color:var(--muted);background:var(--tint)}\n.ticket-items thead th:nth-last-child(-n+2),.ticket-items tbody td:nth-last-child(-n+2){text-align:right}\n.ticket-items tbody td:last-child{font-weight:750}.ticket-items .ticket-note{white-space:normal;text-align:left;font-weight:400}\n@media(max-width:760px){.ticket{padding-inline:7px}.ticket-items th,.ticket-items td{padding-inline:3px}}\n.quantity-actions{grid-column:3;display:flex;gap:4px}.product .quantity-actions button:disabled{opacity:.5}#category-summary{padding:12px 20px;color:var(--accent);font-weight:750;cursor:pointer}.mark-held{color:#a51b1b;font-weight:750}.mark-done{color:#176239;font-weight:750}.hold-choice{display:inline-flex;align-items:center;gap:4px;min-height:34px;cursor:pointer}.hold-choice input{width:18px;height:18px;padding:0}#category-summary{font-size:1.15rem}.category{font-size:1rem}.item-eta{display:block;font-size:.9rem;white-space:nowrap}</style>\n<header class=\"mast\"><div class=\"wrap header-inner\"><b>홍열이네</b><a style=\"color:white\" href=\"/\">발주 화면으로</a></div></header>\n<main class=\"wrap\" style=\"max-width:720px\"><section class=\"hero\"><h1>품목 수정</h1></section>\n<form id=\"gate\" class=\"panel footer\"><label>품목 수정 비밀번호<input id=\"pw\" type=\"password\" required></label><button class=\"primary\">잠금 해제</button></form>\n<section id=\"edit\" class=\"panel footer\" hidden><label>편집할 카테고리<select id=\"categories\"></select></label>\n<label>품목 목록 · 한 줄에 한 품목<textarea id=\"items\" rows=\"9\"></textarea></label>\n<div id=\"prices\"></div><details><summary>카테고리 추가</summary><label>새 카테고리 이름<input id=\"newname\" maxlength=\"70\"></label><button id=\"add\">카테고리 추가</button></details>\n<details><summary>다른 카테고리로 품목 이동</summary><label>이동할 품목<select id=\"source\"></select></label><label>옮길 카테고리<select id=\"target\"></select></label><button id=\"move\">이동</button></details>\n<button class=\"primary\" id=\"save\">변경사항 저장</button></section><p id=\"msg\" role=\"status\"></p></main>\n<style>.price-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)}.price-row strong{grid-column:1/-1}#categories{font-weight:800;color:var(--accent)}#edit>* ,#gate>*{margin-bottom:14px}textarea{font:inherit;padding:10px}summary{cursor:pointer}details label{margin:8px 0}</style>\n<script>function passwordMenu(role,getKey,setKey){\n const panel=document.createElement(\"details\");\n panel.className=\"panel footer\";\n panel.innerHTML='<summary>비밀번호 변경</summary><form><label>새 비밀번호 (4자 이상)<input type=\"password\" required minlength=\"4\" maxlength=\"128\" autocomplete=\"new-password\"></label><label>새 비밀번호 확인<input type=\"password\" required autocomplete=\"new-password\"></label><button>변경 저장</button><p role=\"status\"></p></form>';\n const form=panel.querySelector(\"form\"),[first,again]=form.querySelectorAll(\"input\"),message=form.querySelector(\"p\");\n form.onsubmit=async event=>{\n  event.preventDefault();\n  if(first.value!==again.value){message.textContent=\"두 비밀번호가 일치하지 않습니다.\";return;}\n  const value=first.value,header=role===\"admin\"?\"X-Admin-Password\":\"X-Catalog-Password\";\n  form.inert=true;\n  try{\n   const result=await fetch(\"/api/password/\"+role,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",[header]:encodeURIComponent(getKey())},body:JSON.stringify({password:value})});\n   if(!result.ok){message.textContent=result.status===403?\"다시 로그인해 주세요.\":\"변경하지 못했습니다. 비밀번호와 연결을 확인하세요.\";return;}\n   setKey(value);form.reset();message.textContent=\"비밀번호를 변경했습니다.\";\n  }catch{message.textContent=\"연결을 확인하고 다시 시도하세요.\";}finally{form.inert=false;}\n };\n return panel;\n}\n\n\nconst defaults={\n  \"가루·시즈닝\": \"김가루|치킨반죽가루|뿌링스가루|눈꽃치즈가루|날개가루|홍닭발가루|국물닭발가루|똥집반죽가루|똥집염지가루\",\n  \"식재료·소스\": \"닭껍질|닭목살|오돌뼈|똥집감자|분모자|누룽지|마초고추|참기름|치킨양념소스|치즈소스|치킨간장소스|홍닭발간장|국물닭발간장|다시다\",\n  \"음료·주류·디저트\": \"자몽에이드|자몽에이드탄산|모닌자몽시럽|에이드망고|포도시럽|레몬시럽|작은스프라이트|토닉워터300ml|벨즈|요구르트샤베트\",\n  \"용기·포장\": \"계란탕용기|누룽지용기|막국수용기|오돌뼈용기|주먹밥용기|무용기|콩나물국용기|치킨1인박스|치킨2인박스|배달비닐대|실링필름|영문자기름종이|치킨기름종이|숟가락|젓가락|리필용 스카치테이프\",\n  \"위생·소모품\": \"소독수|식기세척기세제|식기세척기린스|키친타올|핸드타올|테이블냅킨|두루마리휴지|물티슈|앞치마|포스기 영수증(빌지)|튀김기정제필터종이\",\n  \"주방도구·비품\": \"랩칼|석쇠|날개판|뚝배기|주방가위|주방타이머\",\n};\nconst el=id=>document.getElementById(id);\nlet sections=[],index=0,key=\"\",revision=0;\nfunction options(id,choices){el(id).replaceChildren(...choices.map(([title,value])=>new Option(title,value)));}\nconst pricing=new Map();\nfunction priceRows(){\n const panel=el(\"prices\");panel.replaceChildren();\n for(const name of sections[index].items){\n  const row=document.createElement(\"div\");row.className=\"price-row\";\n  const title=document.createElement(\"strong\");title.textContent=name;row.append(title);\n  const record=pricing.get(name)||{name,quantity:\"1\",price:\"\"};pricing.set(name,record);\n  for(const [key,label] of [[\"size\",\"낱개 중량·용량\"],[\"pack\",\"포장당 개입 수\"],[\"price\",\"한 포장 가격(원)\"],[\"quantity\",\"처음 담을 발주 수량\"]]){\n   const field=document.createElement(\"label\"),input=document.createElement(\"input\");\n   field.textContent=label;input.type=\"text\";input.inputMode=[\"pack\",\"price\"].includes(key)?\"numeric\":\"text\";\n   input.value=record[key]??\"\";input.placeholder={size:\"예 1kg 또는 500ml\",pack:\"예 12\",price:\"예 18000\",quantity:\"예 1\"}[key];\n   input.oninput=()=>{record[key]=input.value.trim();el(\"msg\").textContent=\"저장 전 변경사항이 있습니다.\";};\n   field.append(input);row.append(field);\n  }\n  panel.append(row);\n }\n}\nfunction moves(){\n priceRows();\n options(\"source\",sections[index].items.map(n=>[n,n]));\n options(\"target\",sections.flatMap((s,i)=>i===index?[]:[[s.title,i]]));\n}\nfunction draw(){\n options(\"categories\",sections.map((s,i)=>[s.title+\" · \"+s.items.length+\"종\",i]));el(\"categories\").value=index;\n el(\"items\").value=sections[index].items.join(\"\\n\");moves();\n}\nasync function request(path,body){\n const r=await fetch(\"/api/\"+path,body?{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"X-Catalog-Password\":encodeURIComponent(key)},body:JSON.stringify(body)}:{});\n if(!r.ok)throw Error(r.status===403?\"비밀번호를 확인하세요.\":r.status===409?\"다른 기기에서 수정했습니다. 새로고침해 다시 확인하세요.\":\"품목명, 중량·용량(예 500ml), 개입 수(양의 정수), 가격과 발주 수량을 확인하세요.\");\n return r.json();\n}\nel(\"gate\").onsubmit=async e=>{\n e.preventDefault();key=el(\"pw\").value;\n try{await request(\"catalog/unlock\",{});const data=await request(\"state\");revision=data.revision;\n if(data.catalog?.sections){sections=data.catalog.sections;for(const r of data.catalog.pricing||[])pricing.set(r.name,r);}\n else{\n const remaining=new Set(data.catalog||Object.values(defaults).flatMap(v=>v.split(\"|\")));\n sections=Object.entries(defaults).map(([title,v])=>({title,items:v.split(\"|\").filter(n=>remaining.delete(n))}));\n if(remaining.size)sections.push({title:\"내 품목\",items:[...remaining]});\n }\n draw();el(\"pw\").value=\"\";el(\"gate\").hidden=true;el(\"edit\").hidden=false;el(\"edit\").after(passwordMenu(\"catalog\",()=>key,v=>key=v));el(\"msg\").textContent=\"\";\n }catch(e){el(\"msg\").textContent=e.message;}\n};\nel(\"items\").oninput=()=>{sections[index].items=el(\"items\").value.split(\"\\n\").map(n=>n.trim()).filter(Boolean);moves();el(\"msg\").textContent=\"저장 전 변경사항이 있습니다.\";};\nel(\"categories\").onchange=()=>{index=Number(el(\"categories\").value);draw();};\nel(\"add\").onclick=()=>{const title=el(\"newname\").value.trim();if(!title||title.includes(\"|\")||sections.some(s=>s.title===title)){el(\"msg\").textContent=\"새 카테고리 이름을 확인하세요.\";return;}index=sections.push({title,items:[]})-1;el(\"newname\").value=\"\";draw();el(\"msg\").textContent=\"카테고리를 추가했습니다. 변경사항을 저장하세요.\";};\nel(\"move\").onclick=()=>{const n=el(\"source\").value,t=el(\"target\").value;if(!n||!t.length)return;sections[index].items=sections[index].items.filter(v=>v!==n);sections[Number(t)].items.push(n);draw();el(\"msg\").textContent=n+\" 이동 · 변경사항을 저장하세요.\";};\nel(\"save\").onclick=async()=>{el(\"edit\").inert=true;try{await request(\"catalog\",{sections,revision,pricing:sections.flatMap(s=>s.items.map(n=>pricing.get(n)).filter(Boolean))});revision++;el(\"msg\").textContent=\"카테고리와 품목을 저장했습니다.\";}catch(e){el(\"msg\").textContent=e.message;}finally{el(\"edit\").inert=false;}};\n</script></html>\n";
const PAGE="<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"description\" content=\"홍열이네 시청점·인제점·노형점 발주 관리\">\n<title>홍열이네 발주 관리</title>\n<style>:root{color-scheme:light;--ink:#262018;--muted:#655c51;--paper:#fffdf9;--line:#e7e0d5;--accent:#a83223;--deep:#27211c;--warm:#f6f2eb}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--warm);color:var(--ink);font:1rem/1.55 system-ui,-apple-system,\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\nbutton:disabled{cursor:default;opacity:.53}\nbutton:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #c9654b;outline-offset:2px}\n.wrap{width:min(1160px,calc(100% - 48px));margin:auto}\n.mast{background:var(--deep);color:#fff8ee}\n.header-inner{min-height:69px;display:flex;align-items:center;justify-content:space-between;gap:16px}\n.brand{display:flex;align-items:center;gap:11px;font-size:1.13rem;font-weight:850;letter-spacing:-.035em}\n.seal{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:#b63829;color:white}\n.header-label{font-size:.875rem;color:#eadccd}\n.hero{display:flex;align-items:end;justify-content:space-between;gap:24px;padding:42px 0 27px}\n.eyebrow{color:var(--accent);font-size:.875rem;font-weight:800;display:flex;align-items:center;gap:8px}\n.eyebrow span{width:17px;height:2px;background:currentColor}\nh1,h2,h3,p{margin:0}\nh1{font-size:clamp(2.5rem,6vw,3.75rem);line-height:1.16;letter-spacing:-.07em;margin:6px 0 7px}\n.hero p,.panel-header p,.storage{color:var(--muted)}\n.filters{display:flex;gap:12px}\nlabel{display:grid;gap:5px;font-weight:700;font-size:.875rem;color:var(--muted)}\ninput,select{min-width:0;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:1rem}\nselect{appearance:none;padding-right:32px;min-width:105px;background-image:linear-gradient(45deg,transparent 50%,#6a5c51 50%),linear-gradient(135deg,#6a5c51 50%,transparent 50%);background-position:right 16px center,right 11px center;background-size:5px 5px;background-repeat:no-repeat}\n.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:20px;align-items:start;padding-bottom:42px}\n.panel{background:var(--paper);border:1px solid var(--line);border-radius:17px;overflow:hidden;box-shadow:0 3px 10px #38240007}\n.panel-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:19px 21px 14px}\nh2{font-size:1.32rem;letter-spacing:-.035em}\n.panel-header p{font-size:.875rem;margin-top:2px}\n.search{position:relative;display:block;width:min(200px,46%)}\n.search span{position:absolute;left:11px;top:4px;font-size:1.36rem;pointer-events:none}\n.search input{width:100%;padding-left:32px}\n.categories{display:flex;flex-wrap:wrap;gap:6px;padding:0 20px 15px;border-bottom:1px solid var(--line)}\n.category{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:8px;padding:5px 8px;font-size:.875rem;font-weight:650}\n.category[aria-pressed=true]{background:var(--deep);color:white;border-color:var(--deep)}\n.group h3{font-size:.875rem;padding:8px 20px;background:#f7f3eb;color:#5e5145}\n.product{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 20px;border-bottom:1px solid #f0eae0;min-height:44px}\n.product button,.remove{border:1px solid #ecd7cb;border-radius:7px;background:#fff6ef;color:#922b1f;padding:3px 9px;font-size:.875rem;font-weight:700}\n.product button:disabled{opacity:.85;background:#f4efe8;border-color:var(--line);color:var(--muted)}\n.count{display:inline-block;vertical-align:2px;color:var(--accent);background:#f9e9e0;border-radius:7px;padding:0 7px;font-size:.875rem;margin-left:4px}\n.order-list{border-top:1px solid var(--line)}\n.empty{padding:34px 21px;color:var(--muted);text-align:center}\n.line{padding:11px 20px;border-bottom:1px solid #f0eae0}\n.line-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}\n.line-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}\n.line-fields label:last-child{grid-column:1/-1}\n.footer{padding:16px 20px}\n.primary{width:100%;border:0;border-radius:9px;background:var(--accent);color:white;padding:10px;font-weight:800}\n.primary:hover:enabled{background:#8c271b}\n.storage,.status{font-size:.875rem;margin-top:8px}\n.status:empty{display:none}\n.status{color:var(--accent)}\n.copy-field{width:100%;min-height:120px;margin-top:10px;font:inherit}\n@media(max-width:760px){.layout{grid-template-columns:1fr}.hero{align-items:start;flex-direction:column;padding-top:28px;gap:16px}.wrap{width:calc(100% - 28px)}.order{grid-row:1}.order-list .empty{padding:15px 20px}.filters{flex-wrap:wrap}}\n[data-theme=\"시청점\"]{--accent:#175595;--tint:#e9f2fb}\n[data-theme=\"인제점\"]{--accent:#166448;--tint:#e5f4ec}\n[data-theme=\"노형점\"]{--accent:#994315;--tint:#fff0e1}\n[data-theme=\"사모님\"]{--accent:#693b88;--tint:#f4edf8}\n[data-theme=\"품목\"]{--accent:#455368;--tint:#edf0f5}\nbody{background:var(--tint)}\n.mast,.category[aria-pressed=true]{background:var(--accent)}\n.header-label{color:white;font-weight:750}\n.primary:hover:enabled{background:var(--accent);filter:brightness(.88)}\n.product button,.count,#branch{color:var(--accent);background-color:var(--tint);border-color:var(--accent)}\n#branch{font-weight:800}\n.ticket{border-left:5px solid var(--accent);margin:12px 0;padding:12px;background:#fff}\n.branch-badge{display:inline-block;background:var(--accent);color:white;border-radius:6px;padding:2px 9px;margin-right:8px}\n.categories{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:8px}.category{min-height:42px;font-weight:750;color:var(--ink);background:white}.category[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:white}.group h3{font-size:1rem;border-left:5px solid var(--accent);background:var(--tint);color:var(--accent)}#total{display:block;margin-bottom:8px}.product{display:grid;grid-template-columns:minmax(0,1fr) minmax(48px,72px) minmax(68px,104px) 64px;gap:8px;align-items:center}\n.product-name{overflow-wrap:anywhere}.row-field{font-size:.8rem;gap:2px}.row-field input{width:100%;padding:6px;font-variant-numeric:tabular-nums}.product button{min-height:42px;padding:3px}\n@media(max-width:480px){.product{padding:8px 10px;grid-template-columns:minmax(0,1fr) 49px 69px 51px;gap:5px}.product-name{font-size:.94rem}}\n.product{grid-template-columns:minmax(0,1fr) auto auto}.product button{grid-column:3;min-width:54px}.product-heading{display:flex;align-items:baseline;flex-wrap:wrap;gap:2px 12px}.product-values,.cart-quantity{font-size:.875rem;color:var(--muted)}.cart-quantity{color:var(--accent);font-weight:700}.ticket-scroll{max-width:100%;overflow-x:auto;margin:10px 0}\n.ticket-items{width:100%;border-collapse:collapse;font-size:1rem;line-height:1.4;font-variant-numeric:tabular-nums}\n.ticket-items th,.ticket-items td{padding:7px 4px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}\n.ticket-items thead th{font-size:.875rem;color:var(--muted);background:var(--tint)}\n.ticket-items thead th:nth-last-child(-n+2),.ticket-items tbody td:nth-last-child(-n+2){text-align:right}\n.ticket-items tbody td:last-child{font-weight:750}.ticket-items .ticket-note{white-space:normal;text-align:left;font-weight:400}\n@media(max-width:760px){.ticket{padding-inline:7px}.ticket-items th,.ticket-items td{padding-inline:3px}}\n.quantity-actions{grid-column:3;display:flex;gap:4px}.product .quantity-actions button:disabled{opacity:.5}#category-summary{padding:12px 20px;color:var(--accent);font-weight:750;cursor:pointer}.mark-held{color:#a51b1b;font-weight:750}.mark-done{color:#176239;font-weight:750}.hold-choice{display:inline-flex;align-items:center;gap:4px;min-height:34px;cursor:pointer}.hold-choice input{width:18px;height:18px;padding:0}#category-summary{font-size:1.15rem}.category{font-size:1rem}.item-eta{display:block;font-size:.9rem;white-space:nowrap}</style>\n\n</head>\n<body data-theme=\"시청점\">\n<header class=\"mast\">\n  <div class=\"wrap header-inner\"><div class=\"brand\"><span class=\"seal\" aria-hidden=\"true\">홍</span><span>홍열이네</span></div><span class=\"header-label\">매장 운영 / 발주 관리</span></div>\n</header>\n<main class=\"wrap\"><a href=\"/admin\" id=\"admin-link\" style=\"display:inline-block;margin:16px 0;padding:10px 18px;background:#693b88;color:white;border-radius:8px;text-decoration:none\">사모님 관리자</a>\n  <section class=\"hero\">\n    <div><div class=\"eyebrow\"><span></span> 매장 발주표</div><h1>발주 관리</h1><p>지점과 발주일을 선택하고 필요한 품목을 담으세요.</p></div>\n    <div class=\"filters\">\n      <label>지점<select id=\"branch\"><option>시청점</option><option>인제점</option><option>노형점</option></select></label>\n      <label>발주일<input type=\"date\" id=\"date\" required></label>\n    </div>\n  </section>\n  <div class=\"layout\">\n    <section class=\"panel catalog\" aria-labelledby=\"catalog-title\">\n      <div class=\"panel-header\"><div><h2 id=\"catalog-title\">발주 품목</h2><p id=\"catalog-count\"></p></div><label class=\"search\"><span aria-hidden=\"true\">⌕</span><input id=\"search\" type=\"search\" aria-label=\"품목 검색\" placeholder=\"품목 검색\"></label></div>\n      <a style=\"display:inline-block;margin:0 20px 16px\" href=\"/catalog\">품목 수정 페이지</a><details id=\"category-menu\"><summary id=\"category-summary\">품목 선택 · 가루·시즈닝</summary><div class=\"categories\" id=\"categories\" aria-label=\"품목 선택\"></div></details>\n      <div id=\"catalog\"></div>\n    </section>\n    <section class=\"panel order\" aria-labelledby=\"order-title\">\n      <div class=\"panel-header\"><div><h2 id=\"order-title\">발주목록 <span class=\"count\" id=\"count\">0개</span></h2><p id=\"order-date\"></p></div></div>\n      <div id=\"order-list\" class=\"order-list\"></div>\n      <div class=\"footer\"><strong id=\"total\"></strong>\n        <button type=\"button\" class=\"primary\" id=\"send\">발주하기</button><button style=\"margin-top:8px\" type=\"button\" id=\"copy\" disabled>발주 내용 복사</button>\n        <p class=\"storage\" id=\"storage-note\">수정 내용은 이 브라우저에 자동 저장됩니다.</p>\n        <p class=\"status\" id=\"status\" role=\"status\"></p>\n      </div>\n    </section>\n  </div>\n<section class=\"panel\" style=\"padding:20px;margin:0 0 40px\"><h2 id=\"history-heading\">보낸 발주</h2><div id=\"history\"></div></section></main>\n<script>\"use strict\";\n\nconst groups = {\n  \"가루·시즈닝\": \"김가루|치킨반죽가루|뿌링스가루|눈꽃치즈가루|날개가루|홍닭발가루|국물닭발가루|똥집반죽가루|똥집염지가루\",\n  \"식재료·소스\": \"닭껍질|닭목살|오돌뼈|똥집감자|분모자|누룽지|마초고추|참기름|치킨양념소스|치즈소스|치킨간장소스|홍닭발간장|국물닭발간장|다시다\",\n  \"음료·주류·디저트\": \"자몽에이드|자몽에이드탄산|모닌자몽시럽|에이드망고|포도시럽|레몬시럽|작은스프라이트|토닉워터300ml|벨즈|요구르트샤베트\",\n  \"용기·포장\": \"계란탕용기|누룽지용기|막국수용기|오돌뼈용기|주먹밥용기|무용기|콩나물국용기|치킨1인박스|치킨2인박스|배달비닐대|실링필름|영문자기름종이|치킨기름종이|숟가락|젓가락|리필용 스카치테이프\",\n  \"위생·소모품\": \"소독수|식기세척기세제|식기세척기린스|키친타올|핸드타올|테이블냅킨|두루마리휴지|물티슈|앞치마|포스기 영수증(빌지)|튀김기정제필터종이\",\n  \"주방도구·비품\": \"랩칼|석쇠|날개판|뚝배기|주방가위|주방타이머\",\n};\n\nconst element = (id) => document.getElementById(id);\nconst branch = element(\"branch\");\nconst date = element(\"date\");\nconst search = element(\"search\");\nconst copy = element(\"copy\");\nconst status = element(\"status\");\nconst catalog = element(\"catalog\");\nconst orderList = element(\"order-list\");\nconst categoryBar = element(\"categories\");\nconst inMemory = new Map();\nlet category = \"가루·시즈닝\";\nlet order = [];\nlet storageKey = \"\";\nlet activeDate = new Intl.DateTimeFormat(\"sv-SE\", { timeZone: \"Asia/Seoul\" }).format(new Date());\ndate.value = activeDate;\n\nfunction make(tag, className, content) {\n  const node = document.createElement(tag);\n  if (className) node.className = className;\n  if (content) node.textContent = content;\n  return node;\n}\n\nfunction save() {\n  const data = JSON.stringify(order);\n  inMemory.set(storageKey, data);\n  status.textContent = \"\";\n  document.querySelector(\".copy-field\")?.remove();\n  try {\n    localStorage.setItem(storageKey, data);\n  } catch {\n    element(\"storage-note\").textContent = \"브라우저에 저장할 수 없습니다. 페이지를 닫기 전에 발주 내용을 복사하세요.\";\n  }\n}\n\nfunction changeOrder() {\n  if (!date.validity.valid) {\n    date.value = activeDate;\n  }\n  activeDate = date.value;\n  storageKey = [\"hongyeol-orders-v2\", currentUser, branch.value, date.value].join(\"/\");\n  status.textContent = \"\";\n  document.querySelector(\".copy-field\")?.remove();\n  let data = inMemory.get(storageKey);\n  try {\n    data ??= localStorage.getItem(storageKey);\n    order = data ? JSON.parse(data) : [];\n  } catch {\n    order = [];\n  }\n  element(\"order-date\").textContent = branch.value + \" · \" + date.value;\n  render();\n}\n\nfunction priceLabel(price){\n  return price==null||price===\"\"?\"단가 미등록\":Number(price).toLocaleString(\"ko-KR\")+\"원\";\n}\nfunction packageLabel(item={}){\n return [item.size||\"중량·용량 미등록\",item.pack?item.pack+\"개입\":\"개입 수 미등록\",priceLabel(item.price)].join(\" · \");\n}\nfunction renderCatalog() {\n  if(category && !Object.hasOwn(groups,category)) category=Object.keys(groups)[0]||\"\";\n  element(\"category-summary\").textContent=\"품목 선택 · \"+(category||\"전체\");\n  categoryBar.replaceChildren();\n  for (const group of [...Object.keys(groups), \"\"]) {\n    const tab = make(\"button\", \"category\", (group || \"전체\")+\" \"+(group?groups[group].split(\"|\").length:Object.values(groups).reduce((n,v)=>n+v.split(\"|\").length,0)));\n    tab.setAttribute(\"aria-pressed\", String(group === category));\n    tab.onclick = () => {\n      category = group;\n      renderCatalog();\n      element(\"category-menu\").open=false;\n      element(\"category-summary\").focus();\n    };\n    categoryBar.append(tab);\n  }\n\n  const query = search.value.replace(/\\s+/g, \"\").toLowerCase();\n\n  catalog.replaceChildren();\n  let visible = 0;\n  for (const [group, names] of Object.entries(groups)) {\n    if (category && category !== group) continue;\n    const matches = names.split(\"|\").filter((name) => name.replace(/\\s+/g, \"\").toLowerCase().includes(query));\n    if (!matches.length) continue;\n    const section = make(\"section\", \"group\");\n    section.append(make(\"h3\", \"\", group+\" · \"+matches.length+\"종\"));\n    for (const name of matches) {\n      const row = make(\"div\", \"product\");\n      const item = order.find(entry => entry.name === name);\n      const entry=pricing.get(name);\n      const quantity=entry?.quantity||\"1\", price=entry?.price||\"\";\n      const heading=make(\"div\",\"product-heading\");\n      heading.append(make(\"strong\",\"product-name\",name),make(\"small\",\"product-values\",packageLabel(entry)));\n      row.append(heading);\n      if(item)row.append(make(\"span\",\"cart-quantity\",\"담은 수량 \"+item.quantity));\n      const button=make(\"button\",\"\",item?\"+1\":\"+ 담기\");\n      button.setAttribute(\"aria-label\",name+(item?\" 한 개 더 담기\":\" 담기\"));\n      const minus=make(\"button\",\"\",\"− 빼기\");\n      minus.disabled=!item;\n      minus.setAttribute(\"aria-label\",name+\" 한 개 빼기\");\n      function adjust(delta) {\n        if(!item)order.push({name,quantity,price,size:entry?.size||\"\",pack:entry?.pack||\"\",unit:\"\",note:\"\"});\n        else {\n          const raw=item.quantity.trim();\n          const fraction=raw.match(/^(\\d+)\\/(\\d+)$/);\n          const amount=fraction ? Number(fraction[1])/Number(fraction[2]) : Number(raw);\n          if(!Number.isFinite(amount)||amount<0){alert(\"수량을 숫자로 입력한 후 다시 시도해 주세요.\");return;}\n          const next=Number((amount+delta).toFixed(8));\n          if(next<=0)order.splice(order.indexOf(item),1);\n          else item.quantity=String(next);\n        }\n        save();render();\n      };\n      button.onclick=()=>adjust(1);\n      minus.onclick=()=>{if(item)adjust(-1);};\n      const actions=make(\"div\",\"quantity-actions\");\n      actions.append(button,minus);\n      row.append(actions);\n      section.append(row);\n    }\n    visible += matches.length;\n    catalog.append(section);\n  }\n  element(\"catalog-count\").textContent = (category || (query ? \"검색 결과\" : \"전체\")) + \" \" + visible + \"개 품목\";\n  if (!visible) catalog.append(make(\"p\", \"empty\", \"조건에 맞는 품목이 없습니다.\"));\n}\n\nfunction itemCount(items){\n  return new Set(items.map(item=>item.name)).size;\n}\nfunction countLabel(items){return \"발주목록 \"+itemCount(items)+\"개\";}\nfunction totalText(items){\n let total=0,missing=0;\n for(const i of items){\n  const [n,d=\"1\"]=i.quantity.split(\"/\");\n  const q=Number(n)/Number(d);\n  if(!i.price||!/^\\d{1,10}$/.test(i.price)||!Number.isFinite(q)||q<=0){missing++;continue;}\n  total+=Math.round(q*Number(i.price));\n }\n if(items.length && missing===items.length)return \"발주합계 미산정 · 단가 확인 필요\";\n return \"발주합계 \"+total.toLocaleString(\"ko-KR\")+\"원\"+(missing?\" (금액 미산정 \"+missing+\"개 제외)\":\"\");\n}\nfunction renderOrder() {\n  element(\"count\").textContent = itemCount(order)+\"개\";\n  element(\"total\").textContent=totalText(order);\n  copy.disabled = !order.length;\n  orderList.replaceChildren();\n  if (!order.length) orderList.append(make(\"p\", \"empty\", \"발주 품목을 담으면 여기에 표시됩니다.\"));\n\n  for (const item of order) {\n    const line = make(\"div\", \"line\");\n    const title = make(\"div\", \"line-title\");\n    const remove = make(\"button\", \"remove\", \"빼기\");\n    remove.setAttribute(\"aria-label\", item.name + \" 빼기\");\n    remove.onclick = () => {\n      order = order.filter((entry) => entry !== item);\n      save();\n      render();\n      (orderList.querySelector(\".remove\") || search).focus();\n    };\n    title.append(make(\"strong\", \"\", item.name), remove);\n    const values=make(\"p\",\"product-values\",packageLabel(item)+\" · 발주 수량 \"+item.quantity);\n    line.append(title, values);\n    orderList.append(line);\n  }\n}\n\nfunction render() {\n  renderCatalog();\n  renderOrder();\n}\n\ncopy.onclick = async () => {\n  const missing = order.findIndex((item) => !item.quantity.trim());\n  if (missing >= 0) {\n    status.textContent = order[missing].name + \" 수량을 입력하세요.\";\n    orderList.children[missing].querySelector(\".remove\").focus();\n    return;\n  }\n  const lines = order.map(item => {\n    const {name,quantity,unit,note}=item;\n    const amount = [quantity, unit].map((value) => value.trim()).filter(Boolean).join(\" \");\n    return \"- \" + name + \" · \" + packageLabel(item) + \" · 발주 수량 \" + amount + (note.trim() ? \" (\" + note.trim() + \")\" : \"\");\n  });\n  const message = [\"[홍열이네 \" + branch.value + \" 발주]\", date.value, countLabel(order), \"\", ...lines,totalText(order)].join(\"\\n\");\n  document.querySelector(\".copy-field\")?.remove();\n  try {\n    await navigator.clipboard.writeText(message);\n    status.textContent = \"복사했습니다. 카카오톡 등에 붙여넣을 수 있습니다.\";\n  } catch {\n    const field = make(\"textarea\", \"copy-field\");\n    field.readOnly = true;\n    field.value = message;\n    field.setAttribute(\"aria-label\", \"복사할 발주 내용\");\n    status.after(field);\n    field.select();\n    status.textContent = \"선택된 발주 내용을 복사하세요.\";\n  }\n};\n\nsearch.oninput = renderCatalog;\nbranch.onchange = changeOrder;\ndate.onchange = changeOrder;\n</script><script>function passwordMenu(role,getKey,setKey){\n const panel=document.createElement(\"details\");\n panel.className=\"panel footer\";\n panel.innerHTML='<summary>비밀번호 변경</summary><form><label>새 비밀번호 (4자 이상)<input type=\"password\" required minlength=\"4\" maxlength=\"128\" autocomplete=\"new-password\"></label><label>새 비밀번호 확인<input type=\"password\" required autocomplete=\"new-password\"></label><button>변경 저장</button><p role=\"status\"></p></form>';\n const form=panel.querySelector(\"form\"),[first,again]=form.querySelectorAll(\"input\"),message=form.querySelector(\"p\");\n form.onsubmit=async event=>{\n  event.preventDefault();\n  if(first.value!==again.value){message.textContent=\"두 비밀번호가 일치하지 않습니다.\";return;}\n  const value=first.value,header=role===\"admin\"?\"X-Admin-Password\":\"X-Catalog-Password\";\n  form.inert=true;\n  try{\n   const result=await fetch(\"/api/password/\"+role,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",[header]:encodeURIComponent(getKey())},body:JSON.stringify({password:value})});\n   if(!result.ok){message.textContent=result.status===403?\"다시 로그인해 주세요.\":\"변경하지 못했습니다. 비밀번호와 연결을 확인하세요.\";return;}\n   setKey(value);form.reset();message.textContent=\"비밀번호를 변경했습니다.\";\n  }catch{message.textContent=\"연결을 확인하고 다시 시도하세요.\";}finally{form.inert=false;}\n };\n return panel;\n}\n\nlet pricing=new Map();\nconst originals = {...groups};\nconst defaults = Object.values(groups).flatMap(names => names.split(\"|\"));\nconst adminPage = location.pathname === \"/admin\";\nlet currentUser, revision, latestCatalog, busy = false;\n\nconst layout = document.querySelector(\".layout\");\nlayout.inert = true;\nfunction identifyPage(){\n const theme=adminPage?\"사모님\":branch.value;\n document.body.dataset.theme=theme;\n document.querySelector(\".header-label\").textContent=adminPage?\"사모님 · 발주 처리\":theme+\" · 점장\";\n document.querySelector(\"h1\").textContent=adminPage?\"사모님 발주 처리\":theme+\" 발주\";\n if(!adminPage)element(\"send\").textContent=theme+\" 발주하기\";\n}\nidentifyPage();\nbranch.addEventListener(\"change\",identifyPage);\n\nasync function api(path, body, extraHeaders={}) {\n  const headers={};\n  const response = await fetch(\"/api/\"+path, body ? {method:\"POST\",headers:{...headers,...extraHeaders,\"Content-Type\":\"application/json\"},body:JSON.stringify(body)} : {headers});\n  if(response.status===403&&adminPage&&currentUser&&path===\"state?all=1\"){location.reload();throw Error(\"다시 로그인해 주세요.\");}\n  if (!response.ok) throw Error(response.status===409?\"다른 기기에서 변경되었습니다. 새로고침 후 확인하세요.\":\"저장 또는 조회에 실패했습니다. 연결과 권한을 확인하세요.\");\n  return response.json();\n}\nfunction applyCatalog(names) {\n  pricing=new Map((names.pricing||[]).map(r=>[r.name,r]));\n  for(const key of Object.keys(groups)) delete groups[key];\n  if(!Array.isArray(names)){\n    for(const section of names.sections)if(section.items.length)Object.defineProperty(groups,section.title,{value:section.items.join(\"|\"),configurable:true,enumerable:true,writable:true});\n    renderCatalog();return;\n  }\n  const remaining = new Set(names);\n  for(const [group,items] of Object.entries(originals)){\n    const kept = items.split(\"|\").filter(n=>remaining.delete(n));\n    if(kept.length) groups[group]=kept.join(\"|\");\n  }\n  if(remaining.size) groups[\"내 품목\"]=[...remaining].join(\"|\");\n  renderCatalog();\n}\n\nconst holdDrafts=new Map();\nfunction ticketItems(ticket){\n const items=ticket.items;\n const dates=ticket.item_eta?JSON.parse(ticket.item_eta):null;\n const held=ticket.held==null?null:JSON.parse(ticket.held);\n let draft=holdDrafts.get(ticket.id);\n if(!draft||draft.version!==ticket.held){\n   draft={version:ticket.held,selected:new Set(held||[]),periods:{}};\n   if(adminPage&&!ticket.done)holdDrafts.set(ticket.id,draft);\n }\n const wrap=make(\"div\",\"ticket-scroll\");\n const table=make(\"table\",\"ticket-items\");\n table.setAttribute(\"aria-label\",\"발주 품목\");\n const specs=items.some(item=>item.size||item.pack);\n const head=table.createTHead().insertRow();\n const labels=[\"품목\",...(specs?[\"규격\"]:[]),\"포장가\",\"발주량\"];\n const showStatus=adminPage||ticket.done||held!==null;\n if(showStatus)labels.push(\"발주 상태\");\n for(const label of labels){\n   const th=make(\"th\",\"\",label);th.scope=\"col\";head.append(th);\n }\n const body=table.createTBody();\n for(const [index,item] of items.entries()){\n   const line=body.insertRow();\n   const name=make(\"th\",\"\",item.name);name.scope=\"row\";line.append(name);\n   if(specs)line.insertCell().textContent=[item.size,item.pack?item.pack+\"개입\":\"\"].filter(Boolean).join(\" · \")||\"—\";\n   line.insertCell().textContent=item.price!==undefined && item.price!==\"\" && item.price!==null?Number(item.price).toLocaleString(\"ko-KR\")+\"원\":\"—\";\n   line.insertCell().textContent=[item.quantity,item.unit].filter(Boolean).join(\" \");\n   if(showStatus){\n     const cell=line.insertCell();\n     const pending=held?.includes(index);\n     if(ticket.done||(held!==null&&!pending)){\n       cell.append(make(\"span\",\"mark-done\",\"O 발주\"));\n       const eta=dates?dates[index]:ticket.delivery_day;\n       if(eta)cell.append(make(\"small\",\"item-eta\",\"입고 \"+eta));\n\n     }\n     if(!ticket.done&&((adminPage&&held===null)||pending)){\n       const label=make(\"label\",\"hold-choice\");\n       const box=make(\"input\");box.type=\"checkbox\";box.disabled=!adminPage;box.checked=draft.selected.has(index);\n       box.setAttribute(\"aria-label\",item.name+\" 보류\");\n\n       label.append(box,document.createTextNode(\"보류\"));cell.append(label);\n       if(adminPage){\n         const period=make(\"select\");\n         period.setAttribute(\"aria-label\",item.name+\" 입고 기간\");\n         period.append(new Option(\"입고 기간\",\"\"));\n         for(let d=0;d<=7;d++)period.append(new Option(d?d+\"일 후\":\"당일\",String(d)));\n         period.value=draft.periods[index]??\"\";period.hidden=box.checked;\n         period.onchange=()=>{if(period.value===\"\")delete draft.periods[index];else draft.periods[index]=Number(period.value);};\n         box.onchange=()=>{if(box.checked){draft.selected.add(index);delete draft.periods[index];period.value=\"\";}else draft.selected.delete(index);period.hidden=box.checked;};\n         cell.append(period);\n       }\n     }\n   }\n   if(item.note){const cell=body.insertRow().insertCell();cell.colSpan=labels.length;cell.textContent=item.note;cell.className=\"ticket-note\";}\n }\n wrap.append(table);return wrap;\n}\nlet recentOrders=[];\nlet refreshNumber=0;\nasync function refresh(){\n const number=++refreshNumber;\n const data=await api(\"state\"+(adminPage?\"?all=1\":\"\"));\n if(number!==refreshNumber)return;\n if(!currentUser){\n   currentUser=data.user;\n   revision=data.revision;\n   latestCatalog=data.catalog||defaults;\n\n   applyCatalog(latestCatalog);\n   changeOrder();\n   layout.inert=false;\n\n }\n if(data.revision>revision){revision=data.revision;applyCatalog(data.catalog||defaults);}\n recentOrders=data.orders;\n renderHistory();\n}\nfunction renderHistory(){\n const scope=adminPage?\"전체 지점\":branch.value;\n const tickets=adminPage?recentOrders:recentOrders.filter(ticket=>ticket.branch===scope);\n if(!adminPage)element(\"history-heading\").textContent=scope+\" 발주 요청\";\n const history=element(\"history\");\n const wasOpen=history.dataset.scope===scope && history.querySelector(\"details\")?.open;\n history.dataset.scope=scope;\n history.replaceChildren();\n const count=tickets.filter(ticket=>ticket.done).length;\n const completed=make(\"details\");\n completed.open=Boolean(wasOpen);\n completed.append(make(\"summary\",\"\",\"완료 내역 (\"+count+\"건)\"));\n if(!count)completed.append(make(\"p\",\"empty\",\"완료된 발주서가 없습니다.\"));\n if(count===tickets.length)history.append(make(\"p\",\"empty\",\"처리 중인 발주서가 없습니다.\"));\n for(const ticket of tickets){\n   const row=make(\"article\",\"line ticket\");\n   row.dataset.theme=ticket.branch;\n   row.append(make(\"strong\",\"branch-badge\",ticket.branch),make(\"strong\",\"\",ticket.day+\" · \"+(ticket.done?\"발주완료\":ticket.held!=null?\"보류 있음\":\"처리중\")+\" · \"+countLabel(ticket.items)));\n   row.append(ticketItems(ticket));\n   row.append(make(\"strong\",\"\",totalText(ticket.items)));\n   if(ticket.done){\n     holdDrafts.delete(ticket.id);\n   }\n   if(adminPage&&!ticket.done){\n     const btn=make(\"button\",\"primary\",\"발주완료 체크\");\n     btn.onclick=async()=>{\n       const draft=holdDrafts.get(ticket.id);\n       const previous=ticket.held==null?null:JSON.parse(ticket.held);\n       const active=previous??ticket.items.map((_,i)=>i);\n       const missing=active.find(i=>!draft.selected.has(i)&&draft.periods[i]===undefined);\n       if(missing!==undefined){alert(ticket.items[missing].name+\" 입고 기간을 선택하세요.\");return;}\n       btn.disabled=true;\n       try{await api(\"complete\",{id:ticket.id,days:0,periods:draft.periods,held:[...draft.selected],previous});await refresh();}\n       catch(e){alert(e.message);btn.disabled=false;}\n     };\n     row.append(btn);\n   }\n   (ticket.done?completed:history).append(row);\n }\n history.append(completed);\n}\nelement(\"send\").onclick=async()=>{\n if(busy)return;\n if(!order.length||order.some(i=>!i.quantity.trim())){status.textContent=\"품목을 담고 수량을 입력하세요.\";return;}\n const key=storageKey+\"/submission\";\n const payload={branch:branch.value,day:date.value,items:order};\n const fingerprint=JSON.stringify(payload);\n busy=true;layout.inert=true;document.querySelector(\".filters\").inert=true;\n try{\n   const old=JSON.parse(localStorage.getItem(key)||\"null\");\n   const id=old?.fingerprint===fingerprint?old.id:crypto.randomUUID();\n   localStorage.setItem(key,JSON.stringify({id,fingerprint}));\n   const receipt=await api(\"orders\",{id,...payload});\n   order=[];save();localStorage.removeItem(key);render();status.textContent=\"발주목록 \"+receipt.itemCount+\"개가 접수됐습니다. 처리중입니다.\";await refresh();\n }catch(e){status.textContent=e.message;}finally{busy=false;layout.inert=false;document.querySelector(\".filters\").inert=false;}\n};\nif(adminPage){\n layout.style.display=\"none\";document.querySelector(\".filters\").style.display=\"none\";\n document.querySelector(\".eyebrow\").textContent=\"전체 지점\";\n document.querySelector(\".hero p\").textContent=\"거래처 주문을 마친 뒤 발주완료를 체크하세요.\";\n element(\"history-heading\").textContent=\"지점별 발주서\";\n}\nasync function sync(){try{await refresh();}catch(e){element(\"history\").textContent=e.message;}}\nif(adminPage){\n const link=element(\"admin-link\");link.href=\"/?view=manager\";link.textContent=\"점장 화면으로\";\n const gate=make(\"form\",\"panel\");gate.style.padding=\"20px\";\n const label=make(\"label\",\"\",\"관리자 비밀번호\");\n const input=make(\"input\");input.type=\"password\";input.autocomplete=\"current-password\";input.required=true;\n const enter=make(\"button\",\"primary\",\"관리자로 들어가기\");\n const message=make(\"p\",\"status\");message.setAttribute(\"role\",\"status\");\n label.append(input);gate.append(label,enter,message);element(\"history\").before(gate);\n function showControls(){\n   const menu=passwordMenu(\"admin\",()=>\"\",()=>{});\n   const logout=make(\"button\",\"\",\"로그아웃\");\n   logout.onclick=async()=>{try{await api(\"admin/logout\",{});location.reload();}catch(e){alert(e.message);}};\n   gate.replaceWith(menu,logout);\n }\n gate.onsubmit=async e=>{e.preventDefault();enter.disabled=true;\n try{await api(\"admin/login\",{},{\"X-Admin-Password\":encodeURIComponent(input.value)});input.value=\"\";await refresh();showControls();}\n catch{message.textContent=\"접속하지 못했습니다. 비밀번호와 연결을 확인하세요.\";}\n finally{enter.disabled=false;}};\n gate.hidden=true;\n refresh().then(showControls).catch(()=>{gate.hidden=false;});\n}else {\n branch.addEventListener(\"change\",renderHistory);\n sync();\n}\nsetInterval(()=>{if(!document.hidden&&(!adminPage||currentUser))sync();},10000);window.addEventListener(\"focus\",()=>{if(!adminPage||currentUser)sync();});\n\nwindow.addEventListener(\"pageshow\",event=>{if(event.persisted&&!adminPage)location.reload();});\n</script></body>\n</html>\n";
const json=(data,status=200)=>Response.json(data,{status,headers:{"Cache-Control":"no-store"}});
const field=(s,n)=>typeof s==="string" && s.length<=n;
async function hashPassword(value,salt){
 const encoder=new TextEncoder();
 const key=await crypto.subtle.importKey("raw",encoder.encode(value),"PBKDF2",false,["deriveBits"]);
 const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:encoder.encode(salt),iterations:100000,hash:"SHA-256"},key,256);
 return Array.from(new Uint8Array(bits),n=>n.toString(16).padStart(2,"0")).join("");
}
async function credential(req,env,role){
 const header=req.headers.get(role==="admin"?"X-Admin-Password":"X-Catalog-Password");
 if(!header)return null;
 let password;
 try{password=decodeURIComponent(header);}catch{return null;}
 if(password.length>128)return null;
 const record=await env.DB.prepare("SELECT salt,digest FROM role_passwords WHERE role=?").bind(role).first();
 if(record)return await hashPassword(password,record.salt)===record.digest?record:null;
 const initial=role==="admin"?env.ADMIN_PASSWORD:env.CATALOG_PASSWORD;
 return initial && password===initial?{}:null;
}
const tokenHash=async token=>Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(token))),n=>n.toString(16).padStart(2,"0")).join("");
async function sessionResponse(db,user,version){
 const token=crypto.randomUUID();
 await db.prepare("DELETE FROM admin_sessions WHERE expires<=?").bind(Date.now()).run();
 await db.prepare("INSERT INTO admin_sessions VALUES(?,?,?,?)").bind(await tokenHash(token),user,version,Date.now()+86400000).run();
 return Response.json({},{headers:{"Cache-Control":"no-store","Set-Cookie":"__Host-hy_admin="+token+"; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=86400"}});
}
const priceOK=p=>p===""||(typeof p==="string"&&/^\d{1,10}$/.test(p));
const quantityOK=q=>typeof q==="string"&&q.length<=32&&(/^(?:\d+(?:\.\d+)?|\.\d+)$/.test(q)?Number(q)>0:/^[1-9]\d*\/[1-9]\d*$/.test(q));
function packageOK(r){
 const size=r.size??"",pack=r.pack??"";
 return typeof size==="string"&&size.length<=32&&(!size||(/^\d+(?:\.\d+)?\s*(kg|g|ml|l)$/i.test(size)&&parseFloat(size)>0))&&typeof pack==="string"&&(!pack||/^[1-9]\d{0,6}$/.test(pack));
}
export default {async fetch(req,env){
 const path=new URL(req.url).pathname, url=new URL(req.url);
 const signedIn=req.headers.get("oai-authenticated-user-id");
 let token=(req.headers.get("Cookie")||"").match(/(?:^|; *)__Host-hy_device=([a-f0-9]{64})(?:;|$)/)?.[1];
 const page=req.method==="GET"&&["/","/admin","/catalog"].includes(path);
 if(page){
  const headers={"content-type":"text/html;charset=utf-8","cache-control":"private,no-store"};
  const cookies=req.headers.get("Cookie")||"";
  const hasAdmin=/(?:^|; *)__Host-hy_admin=[a-f0-9-]{36}(?:;|$)/.test(cookies);
  const managerMode=/(?:^|; *)hy_view=manager(?:;|$)/.test(cookies);
  if(path==="/"&&url.searchParams.get("view")==="manager"){
   return new Response(null,{status:302,headers:{...headers,Location:"/","Set-Cookie":"hy_view=manager; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=86400"}});
  }
  if(path==="/"&&hasAdmin&&!managerMode)return new Response(null,{status:302,headers:{...headers,Location:"/admin"}});
  if(path==="/admin"&&managerMode)headers["Set-Cookie"]="hy_view=; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=0";
  if(!token&&!signedIn){
   token=Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,"0")).join("");
   headers["Set-Cookie"]="__Host-hy_device="+token+"; Path=/; Max-Age=31536000; Secure; HttpOnly; SameSite=Lax";
  }
  return new Response(path==="/catalog"?EDITOR:PAGE,{headers});
 }
 if(!signedIn&&!token)return json({},401);
 const user=signedIn||"device-"+Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(token))),v=>v.toString(16).padStart(2,"0")).join("");
 const db=env.DB;
 let admin=await credential(req,env,"admin");
 const session=(req.headers.get("Cookie")||"").match(/(?:^|; *)__Host-hy_admin=([a-f0-9-]{36})(?:;|$)/)?.[1];
 if(!admin && session && path!=="/api/admin/login"){
  const row=await db.prepare("SELECT p.digest FROM admin_sessions s LEFT JOIN role_passwords p ON p.role='admin' WHERE s.token=? AND s.owner=? AND s.expires>? AND s.version=COALESCE(p.salt,'initial')").bind(await tokenHash(session),user,Date.now()).first();
  if(row)admin=row;
 }
 if((path==="/api/complete" || (path==="/api/state" && url.searchParams.get("all")==="1")) && !admin)return json({},403);
 if(req.method==="GET"&&path==="/api/state"){
  const query=admin&&url.searchParams.get("all")==="1"?db.prepare("SELECT * FROM orders ORDER BY done,created DESC"):db.prepare("SELECT * FROM orders WHERE owner=? ORDER BY created DESC").bind(user);
  const [catalog,orders]=await Promise.all([db.prepare("SELECT data,revision FROM catalogs ORDER BY rowid LIMIT 1").first(),query.all()]);
  return json({user,admin:!!admin,catalog:catalog?JSON.parse(catalog.data):null,revision:catalog?.revision||0,orders:orders.results.map(({owner,...o})=>({...o,items:JSON.parse(o.items)}))});
 }
 if(req.method!=="POST"||req.headers.get("origin")!==url.origin||!req.headers.get("content-type")?.startsWith("application/json"))return json({},403);
 const b=await req.json().catch(()=>null);
 if(!b||typeof b!=="object")return json({},400);
 if(path==="/api/admin/login")return admin?sessionResponse(db,user,admin.salt||"initial"):json({},403);
 if(path==="/api/admin/logout"){
  if(session)await db.prepare("DELETE FROM admin_sessions WHERE token=?").bind(await tokenHash(session)).run();
  return Response.json({},{headers:{"Set-Cookie":"__Host-hy_admin=; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=0"}});
 }
 if(path==="/api/password/admin" || path==="/api/password/catalog"){
  const role=path.endsWith("/admin")?"admin":"catalog";
  const old=role==="admin"?admin:await credential(req,env,role);
  if(!old)return json({},403);
  if(!field(b.password,128)||b.password.trim().length<4)return json({},400);
  const salt=crypto.randomUUID(), digest=await hashPassword(b.password,salt);
  const result=old.digest
    ?await db.prepare("UPDATE role_passwords SET salt=?,digest=? WHERE role=? AND digest=?").bind(salt,digest,role,old.digest).run()
    :await db.prepare("INSERT OR IGNORE INTO role_passwords VALUES(?,?,?)").bind(role,salt,digest).run();
  if(result.meta.changes && role==="admin")return sessionResponse(db,user,salt);
  return json({},result.meta.changes?200:409);
 }
 if(path==="/api/catalog" || path==="/api/catalog/unlock"){
  if(!await credential(req,env,"catalog"))return json({},403);
  if(path==="/api/catalog/unlock")return json({});

  let names=b.names, catalog=names;
  if(b.sections){
   const valid=s=>field(s,70)&&s.trim()===s&&!!s&&!s.includes("|");
   if(!Array.isArray(b.sections)||b.sections.length>200||!b.sections.every(g=>g&&valid(g.title)&&Array.isArray(g.items))||new Set(b.sections.map(g=>g.title)).size!==b.sections.length)return json({},400);
   names=b.sections.flatMap(g=>g.items);catalog={sections:b.sections};
  }
  if(!Array.isArray(names)||!names.length||names.length>1000||!names.every(n=>field(n,70)&&n.trim()===n&&n&&!n.includes("|"))||new Set(names).size!==names.length)return json({},400);
  if(b.pricing!==undefined){
   const allowed=new Set(names);
   if(!b.sections||!Array.isArray(b.pricing)||b.pricing.length>names.length||!b.pricing.every(r=>r&&allowed.has(r.name)&&packageOK(r)&&quantityOK(r.quantity)&&priceOK(r.price))||new Set(b.pricing.map(r=>r.name)).size!==b.pricing.length)return json({},400);
   catalog.pricing=b.pricing.map(({name,quantity,price,size="",pack=""})=>({name,quantity,price,size,pack}));
  }
  const data=JSON.stringify(catalog);
  const result=b.revision===0?await db.prepare("INSERT OR IGNORE INTO catalogs SELECT ?,?,1 WHERE NOT EXISTS(SELECT 1 FROM catalogs)").bind("shared",data).run():await db.prepare("UPDATE catalogs SET data=?,revision=revision+1 WHERE rowid=(SELECT MIN(rowid) FROM catalogs) AND revision=?").bind(data,b.revision).run();
  return json({},result.meta.changes?200:409);
 }
 if(path==="/api/orders"){
  if(!field(b.id,50)||!b.id||!["시청점","인제점","노형점"].includes(b.branch)||!/^\d{4}-\d\d-\d\d$/.test(b.day)||!Array.isArray(b.items)||!b.items.length||b.items.length>1000||!b.items.every(i=>i&&packageOK(i)&&field(i.name,70)&&i.name.trim()&&field(i.quantity,32)&&i.quantity.trim()&&field(i.unit,32)&&field(i.note,150)&&(i.price===undefined||priceOK(i.price))&&(!i.price||quantityOK(i.quantity))))return json({},400);
  const items=JSON.stringify(b.items);
  await db.prepare("INSERT OR IGNORE INTO orders (id,owner,branch,day,items,created,done) VALUES(?,?,?,?,?,?,0)").bind(b.id,user,b.branch,b.day,items,Date.now()).run();
  const saved=await db.prepare("SELECT owner,items,branch,day FROM orders WHERE id=?").bind(b.id).first();
  if(saved.owner!==user||saved.items!==items||saved.branch!==b.branch||saved.day!==b.day)return json({},409);
  return json({itemCount:new Set(JSON.parse(saved.items).map(item=>item.name)).size});
 }
 if(path==="/api/complete" && field(b.id,50)){
  if(!Number.isInteger(b.days)||b.days<0||b.days>7)return json({},400);
  const order=await db.prepare("SELECT items,held,done,item_eta,delivery_day FROM orders WHERE id=?").bind(b.id).first();
  if(!order)return json({},404);
  if(order.done)return json({});
  const previous=order.held===null?null:JSON.parse(order.held);
  const held=b.held??[];
  const size=JSON.parse(order.items).length;
  if(!Array.isArray(held)||held.length>size||new Set(held).size!==held.length||!held.every(i=>Number.isInteger(i)&&i>=0&&i<size))return json({},400);
  if(JSON.stringify(previous)!==JSON.stringify(b.previous??null)||previous&&held.some(i=>!previous.includes(i)))return json({},409);
  const eta=order.item_eta?JSON.parse(order.item_eta):Array.from({length:size},(_,i)=>previous&&!previous.includes(i)?order.delivery_day:null);
  const today=new Date(Date.now()+9*3600000).toISOString().slice(0,10);
  const periods=b.periods??{};
  for(let i=0;i<size;i++){
   if(held.includes(i)||(previous&&!previous.includes(i)))continue;
   const days=b.periods===undefined?b.days:periods[i];
   if(!Number.isInteger(days)||days<0||days>7)return json({},400);
   eta[i]=new Date(Date.parse(today+"T00:00:00Z")+days*86400000).toISOString().slice(0,10);
  }
  const result=await db.prepare("UPDATE orders SET held=?,done=?,item_eta=?,delivery_days=NULL,delivery_day=NULL WHERE id=? AND done=0 AND held IS ?").bind(JSON.stringify(held.sort((a,b)=>a-b)),held.length?0:1,JSON.stringify(eta),b.id,order.held).run();
  return json({},result.meta.changes?200:409);
 }
 return json({},404);
}};
